const{Extension:Extension}=TiptapCore;export const Base64ImageHandler=Extension.create({name:"base64ImageHandler",addOptions(){return{uploadHandler:null}},onTransaction({transaction:t}){if(!this.options.uploadHandler||!t.docChanged||!this.editor.isEditable){return}const e=this.editor;const s=this.options.uploadHandler;const a=[];e.state.doc.descendants((t,e)=>{if(t.type.name==="image"&&(t.attrs.src||"").startsWith("data:")){a.push({pos:e,attrs:{...t.attrs}})}});if(a.length===0){return}let n=e.state.tr;for(const{pos:t,attrs:r}of a){const a=crypto.randomUUID();const i=`about:uploading-${a}`;const o=r.src;n=n.setNodeMarkup(t,undefined,{...r,src:i});s(o).then(t=>{if(e.isDestroyed){return}e.state.doc.descendants((s,a)=>{if(s.type.name==="image"&&s.attrs.src===i){if(t){e.view.dispatch(e.state.tr.setNodeMarkup(a,undefined,{...s.attrs,src:t}))}else{e.view.dispatch(e.state.tr.delete(a,a+s.nodeSize))}return false}})}).catch(()=>{if(e.isDestroyed){return}e.state.doc.descendants((t,s)=>{if(t.type.name==="image"&&t.attrs.src===i){e.view.dispatch(e.state.tr.delete(s,s+t.nodeSize));return false}})})}queueMicrotask(()=>{if(!e.isDestroyed){e.view.dispatch(n)}})}});